using namespace std;

class Node
{
public:
  int data = 0;
  Node* next = nullptr;

  Node(int data)
  {
    this->data = data;
  }
};



class linkedlist
{

public:

  Node* head = nullptr;
  Node* tail = nullptr;
  int size = 0;

  //basic->============================================

  int size_()
  {
    return this->size;
  }

  bool isEmpty()
  {
    return this->size == 0;
  }

  string toString()
  {
    Node* curr = this->head;
    string sb = "";

    while (curr != nullptr)
    {
      sb += to_string(curr->data);
      if (curr->next != nullptr)
        sb += " ";
      curr = curr->next;
    }
    return sb;
  }

  //add->===============================================
private:
  void addFirstNode(Node* node)
  {
    if (this->head == nullptr)
    {
      this->head = node;
      this->tail = node;
    }
    else
    {
      node->next = this->head;
      this->head = node;
    }

    this->size++;
  }

public:
  void addFirst(int val)
  {
    Node* node = new Node(val);
    addFirstNode(node);
  }

public:
  void addLastNode(Node* node)
  {
    if (this->head == nullptr)
    {
      this->head = node;
      this->tail = node;
    }
    else
    {
      this->tail->next = node;
      this->tail = node;
    }

    this->size++;
  }

  void addLast(int val)
  {
    Node* node = new Node(val);
    addLastNode(node);
  }

  void addNodeAt(Node* node, int idx)
  {
    if (idx == 0)
      addFirstNode(node);
    else if (idx == this->size)
      addLastNode(node);
    else
    {
      Node* prev = getNodeAt(idx - 1);
      Node* curr = prev->next;

      prev->next = node;
      curr->next = node;

      this->size++;
    }
  }

  void addAt(int data, int idx)
  {
    if (idx < 0 || idx > this->size)
    {
      throw ("invalidLocation: " + to_string(idx));
    }

    Node* node = new Node(data);
    addNodeAt(node, idx);
  }

  //remove->============================================
  Node* removeFirstNode()
  {
    Node* node = this->head;
    if (this->size == 1)
    {
      this->head = nullptr;
      this->tail = nullptr;
    }
    else
    {
      this->head = this->head->next;
      node->next = nullptr;
    }

    this->size--;
    return node;
  }

  int removeFirst(int val)
  {
    if (this->size == 0)
    {
      throw ("nullptrPointerException: -1");
    }

    Node* node = removeFirstNode();
    int rv = node->data;
    delete node;
    return rv;
  }

  Node* removeLastNode()
  {
    Node* node = this->tail;
    if (this->size == 1)
    {
      this->head = nullptr;
      this->tail = nullptr;
    }
    else
    {
      Node* prev = getNodeAt(this->size - 2);
      this->tail = prev;
      prev->next = nullptr;
    }

    this->size--;
    return node;
  }

  int removeLast(int val)
  {
    if (this->size == 0)
    {
      throw ("nullptrPointerException: -1");
    }

    Node* node = new Node(val);
    int rv = node->data;
    delete node;
    return rv;
  }

  Node* removeNodeAt(int idx)
  {
    if (idx == 0)
      return removeFirstNode();
    else if (idx == this->size - 1)
      return removeLastNode();
    else
    {

      Node* prev = getNodeAt(idx - 1);
      Node* curr = prev->next;

      prev->next = curr->next;
      curr->next = nullptr;

      this->size--;
      return curr;
    }
  }

  int removeAt(int idx)
  {
    if (idx < 0 || idx >= this->size)
    {
      throw ("invalidLocation: " + idx);
    }

    Node* node = removeNodeAt(idx);
    int rv = node->data;
    delete node;
    return rv;
  }

